import { build } from "esbuild";
import { workflowIds as ids, workflowId, workflowLine } from "./upgrade-workflow-actions-fixture.mjs";

export async function buildWorkflowBrowserBundle() {
  const profile = { id: ids.profile, profile_code: "AL-101", profile_name: "Window section", section_weight_kg_per_m: 0.8, section_perimeter_mm: 120, drawing_revision: "B", drawing_approval_status: "approved" };
  const customer = { id: ids.customer, customer_name: "Mira Shah", company_name: "Mira Aluminium Window Systems", gst_number: null, billing_address: null, shipping_address: null };
  const order = { id: ids.order, order_number: "ORD-100", current_stage: "packing", customer_name: customer.customer_name, company_name: customer.company_name };
  const source = { id: ids.source, sourceKind: "production", sourceLabel: "JOB-100 / packaging released", profileId: ids.profile, profileLabel: "AL-101 Window section", stockBatchId: null, stockBatchLabel: null, availableWeightKg: 1000, availablePieces: 100, availableLengthM: 600 };
  const aliases = {
    "@/lib/supabase/browser": `
      const profile=${JSON.stringify(profile)},customer=${JSON.stringify(customer)},order=${JSON.stringify(order)};
      export function createClient(){return {from(table){let single=false;const filters=[];const q={select(){return q},eq(key,value){filters.push([key,value]);return q},neq(){return q},is(){return q},order(){return q},limit(){return q},or(){return q},ilike(){return q},in(){return q},maybeSingle(){single=true;return q},then(resolve,reject){let data=table==="aluminium_profiles"?[profile]:table==="customers"?[customer]:table==="orders_authorized"?[order]:[];if(table==="company_settings_authorized")data={default_quote_validity_days:15,default_gst_percent:18,default_margin_percent:10,default_conversion_charge_per_kg:30,minimum_margin_percent:8};else if(single)data=data[0]??null;return Promise.resolve({data,error:null}).then(resolve,reject)}};return q}};}
    `,
    "@/lib/actions/quotes-orders": `export async function saveQuoteAction(input){window.fixture.quoteWrites.push(input);return {success:true,quoteId:"${workflowId(999)}"}} export async function updateQuoteStatusAction(){return {success:false,error:"Not part of the fixture"}}`,
    "@/lib/actions/repeat-quote": `import {repeatQuoteDraft} from "@/lib/forms/repeat-quote";export async function repeatQuoteAction(id){if(window.fixture.repeatHandler)return window.fixture.repeatHandler(id);return {success:true,sourceNumber:"QT-OLD / Rev 3",draft:repeatQuoteDraft({customer_id:"${ids.customer}",valid_until:"2020-01-01",gst_percent:18,terms_and_conditions:"Payment within 30 days",notes:"Copied source note"},[${JSON.stringify(workflowLine)}],[${JSON.stringify(profile)}],"2026-10-21","2026-11-05"),customer:${JSON.stringify(customer)},profiles:[${JSON.stringify(profile)}]}}`,
    "@/lib/actions/in-task-customers": `export async function inTaskCustomerAction(){return {kind:"error",error:"Use the customer-creation acceptance fixture for this action"}}`,
    "@/lib/actions/instant-search": `import {cleanFindQuery} from "@/lib/workflow/instant-search";export async function instantFindAction(query){window.fixture.findQueries.push(query);if(window.fixture.findHandler)return window.fixture.findHandler(query);const cleaned=cleanFindQuery(query);return {query:cleaned,unavailable:cleaned==="unavailable"?["orders"]:[],items:cleaned==="unavailable"||cleaned==="nothing"?[]:[{id:"${ids.order}",resource:"orders",title:"ORD-100",detail:"Mira Aluminium Window Systems / Mira Shah",status:"packing",href:"/orders/${ids.order}",action:{label:"Check dispatch readiness",href:"/dispatches/new?order_id=${ids.order}"}},{id:"${ids.quote}",resource:"quotes",title:"QT-OLD / Rev 3",detail:"Previous commercial quotation",status:"expired",href:"/quotes/${ids.quote}",action:{label:"Repeat quotation",href:"/quotes/new?repeat_from=${ids.quote}"}}]}}`,
    "@/lib/actions/order-stage-age": `export async function orderStageAgeAction(ids){window.fixture.stageQueries.push(ids);if(window.fixture.stageHandler)return window.fixture.stageHandler(ids);return {rows:[{id:"${ids.order}",label:"ORD-100",stage:"packing",enteredAt:new Date(Date.now()-49*3600000).toISOString(),dueDate:"2026-10-25"},{id:"${workflowId(41)}",label:"ORD-101",stage:"production_in_progress",enteredAt:null,dueDate:null,reason:"Current stage entry is not recorded"}]}}`,
    "@/lib/actions/dispatches": `export async function getDispatchSourcesAction(id){window.fixture.sourceQueries.push(id);if(window.fixture.sourceHandler)return window.fixture.sourceHandler(id);return {success:true,sources:[${JSON.stringify(source)}]}}export async function saveDispatchAction(input){window.fixture.dispatchWrites.push(input);if(window.fixture.dispatchHandler)return window.fixture.dispatchHandler(input);return {success:true,dispatchId:"${workflowId(998)}"}}`,
    "@/lib/actions/dispatch-order-balance": `export async function dispatchOrderBalanceAction(id){window.fixture.balanceQueries.push(id);if(window.fixture.balanceHandler)return window.fixture.balanceHandler(id);return {success:true,balance:{orderId:id,orderLabel:"ORD-100 - Mira Aluminium Window Systems",ordered:{pieces:120,metres:720},shipped:{pieces:20,metres:120}}}}`,
    "next/navigation": `export function useRouter(){return {push(url){window.fixture.navigations.push(url)},refresh(){}}}`,
    "next/link": `import React from "react";export default function Link({children,...props}){return <a {...props}>{children}</a>}`,
    "sonner": `export const toast={error(text){window.fixture.errors.push(text);document.getElementById("fixture-message").textContent=text},success(text){document.getElementById("fixture-message").textContent=text},warning(){}};`,
  };
  const bundle = await build({ stdin: { resolveDir: process.cwd(), sourcefile: "workflow-acceptance.tsx", loader: "tsx", contents: `
    import React from "react";import {createRoot} from "react-dom/client";import {QuotesClient} from "./components/modules/quotes-client";import {DispatchFormClient} from "./components/modules/dispatch-form-client";import {InstantFind} from "./components/search/instant-find";import {StageWaiting} from "./components/modules/orders/stage-waiting";
    window.fixture={quoteWrites:[],dispatchWrites:[],sourceQueries:[],balanceQueries:[],findQueries:[],stageQueries:[],errors:[],navigations:[]};
    const root=createRoot(document.getElementById("app"));const context={companyId:"${ids.company}",userId:"${ids.user}",role:"owner"};
    window.renderWorkflow=(screen,extra={})=>root.render(<React.Fragment key={JSON.stringify([screen,extra])}>{screen==="search"?<InstantFind/>:screen==="repeat"?<QuotesClient context={context} mode="form" repeatFromId="${ids.quote}"/>:screen==="dispatch"?<DispatchFormClient context={context} initialOrderId="${ids.order}"/>:screen==="stage"?<><h1 className="text-3xl font-black mb-5">Order stage waiting times</h1><StageWaiting orderIds={["${ids.order}"]}/></>:null}</React.Fragment>);
    const query=new URLSearchParams(window.location.search);const screen=window.location.pathname.startsWith("/dispatches/new")?"dispatch":window.location.pathname.startsWith("/quotes/new")?"repeat":query.get("screen")||"search";window.renderWorkflow(screen);
    document.querySelectorAll("[data-workflow-screen]").forEach(button=>button.addEventListener("click",()=>window.renderWorkflow(button.dataset.workflowScreen)));
  ` }, bundle: true, write: false, platform: "browser", format: "iife", jsx: "automatic", plugins: [{ name: "workflow-fixture-boundaries", setup(api) {
    api.onResolve({ filter: /^(?:@\/lib\/(?:supabase\/browser|actions\/(?:quotes-orders|repeat-quote|in-task-customers|instant-search|order-stage-age|dispatches|dispatch-order-balance))|next\/(?:navigation|link)|sonner)$/ }, ({ path }) => ({ path, namespace: "fixture" }));
    api.onLoad({ filter: /.*/, namespace: "fixture" }, ({ path }) => ({ contents: aliases[path], loader: "tsx", resolveDir: process.cwd() }));
  } }] });
  return bundle.outputFiles[0].text;
}
